# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::ReservationAccess do
  # "The background credential (`TIMEKEEPING_SERVICE_TOKEN`) is bound to one
  # `company_id` per request and allowed only these operations:
  # `reservations.prepare`, `reservations.commit`, `reservations.abort`,
  # `invoices.mark_billed`, `entries.import`, `agents.detach_entries`."
  # "An anonymous or user-delegated request never gets it."
  it "allows only a verified service token for its own company and listed background operation" do
    secret = "service-#{SecureRandom.hex(24)}"
    public_key = rsa_key_pair.public_key.to_pem
    resolve = lambda do |token|
      Timekeeping::Identity.resolve(authorization: token && "Bearer #{token}", public_key:, service_token: secret)
    end
    service_token = lambda do |operations|
      JWT.encode({ typ: "timekeeping_service", sub: "invoice-boundary", company_id: 1, operations:,
                   exp: Time.now.to_i + 300, jti: SecureRandom.uuid }, secret, "HS256")
    end
    bound = resolve.call(service_token.call(["reservations.prepare", "entries.delete"]))
    owner = resolve.call(mint_token({ sub: 7, company_id: 1, role: "owner" }))

    expect(described_class.decide(identity: bound, company_id: 1, operation: "reservations.prepare")).to eq(:allowed)
    expect(described_class.decide(identity: bound, company_id: 2, operation: "reservations.prepare")).to eq(:not_found)
    expect(described_class.decide(identity: bound, company_id: 1, operation: "reservations.commit")).to eq(:forbidden)
    expect(described_class.decide(identity: bound, company_id: 1, operation: "entries.delete")).to eq(:forbidden)
    expect(described_class.decide(identity: owner, company_id: 1, operation: "reservations.prepare")).to eq(:forbidden)
    expect(described_class.decide(identity: resolve.call(secret), company_id: 1, operation: "reservations.prepare"))
      .to eq(:forbidden)
    expect(described_class.decide(identity: resolve.call(nil), company_id: 1, operation: "reservations.prepare"))
      .to eq(:unauthorized)
  end
end
